head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Workflow > P > rejectCallback]<br/>Workflow 모듈의 작업 처리 도중 오류가 발생했을 때 실행할 콜백 함수를 설정합니다.",
    "validation" : [
        "Workflow 모듈 처리중 에러 발생 시 실행할 콜백 함수를 설정할 수 있어야 합니다.",
        "콜백 함수에는 Workflow 객체가 파라미터로 전달되어야 합니다.",
        "Workflow 모듈 처리중 Submission 오류나 타임아웃, 예외가 발생하면 콜백 함수가 1 회 실행되어야 합니다."
    ]
}

scwin.gVar = { "rejectCount" : 0, "paramType" : "undefined", "paramId" : "-" };

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};

// workflow 마지막 step (Submission 오류로 중단되므로 실행되지 않음)
scwin.wf_step_last = function () {
    return true;
};

// rejectCallback - 호출 횟수와 전달받은 파라미터 정보를 수집
scwin.wf_rejectCallback = function (workflowObj) {
    scwin.gVar.rejectCount = scwin.gVar.rejectCount + 1;
    scwin.gVar.paramType = (typeof workflowObj);
    scwin.gVar.paramId = (workflowObj && workflowObj.id) ? workflowObj.id : "-";
};

scwin.btn_run_onclick = function () {
    scwin.gVar.rejectCount = 0;
    scwin.gVar.paramType = "undefined";
    scwin.gVar.paramId = "-";

    var wfObj = $p.getWorkflow("wf_reject");
    var declId = wfObj ? wfObj.id : "-";

    wf_body_bottom.getObj("scwin").setReturnValue("wf_reject 의 rejectCallback 설정값 : " + (wfObj ? wfObj.rejectCallback : "-"));

    $p.executeWorkflow("wf_reject");

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 파라미터 타입 : " + scwin.gVar.paramType + " / 파라미터의 id : " + scwin.gVar.paramId + " (선언한 Workflow 객체의 id : " + declId + ")");
        wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 실행 횟수 : " + scwin.gVar.rejectCount);
    }, 5000);
};
